// n8n Code node: "Debounce & Combine"
// Mode: Run Once for All Items
//
// Production replacement for twilio_buffer.js.
//
// Why: Twilio fires one webhook per SMS, and n8n starts one execution per
// webhook, so $input.all() inside a single execution only ever holds that one
// message. Aggregation therefore has to happen in shared state (the
// "eric_sms_buffer" n8n Data Table) instead of in memory.
//
// Flow before this node:
//   Webhook -> insert row into eric_sms_buffer -> Wait 15s -> get all buffered
//   rows for this sender (sorted ASC).
//
// Debounce rule: only the execution that owns the NEWEST buffered message for
// this phone number continues. Every earlier execution returns [] and stops,
// so the lead gets exactly one reply per burst of texts. The grouping/joining
// output shape matches twilio_buffer.js so downstream nodes see the same fields.

const config = $('Eric Config').first().json;
if (!config.ghlConversationProviderId) {
  throw new Error(
    'Eric Config.ghlConversationProviderId is empty. Create the GHL Custom SMS ' +
    'Conversation Provider (README step 2) and paste its ID into the Eric Config node.'
  );
}

const trigger = $('Twilio Inbound Webhook').first().json.body;
const mySid = trigger.MessageSid;

const rows = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row && row.messageSid && row.phone === trigger.From)
  .sort((a, b) => Number(a.id) - Number(b.id));

if (rows.length === 0) {
  // Another execution already consumed and cleared this burst.
  return [];
}

const latest = rows[rows.length - 1];
if (latest.messageSid !== mySid) {
  // A newer text arrived inside the window; that execution will reply.
  return [];
}

const messages = rows
  .map((row) => (row.body || '').trim())
  .filter((body) => body.length > 0);

if (messages.length === 0) {
  return [];
}

return [
  {
    json: {
      phoneNumber: trigger.From,
      twilioNumber: trigger.To,
      combinedMessage: messages.join(' \n '),
      individualMessages: messages,
      messageCount: rows.length,
      messageSids: rows.map((row) => row.messageSid),
      lastMessageSid: mySid,
      maxBufferRowId: Number(latest.id),
      originalTwilioData: trigger,
      timestamp: new Date().toISOString(),
    },
  },
];

// n8n Code node: "Build Eric Context"
// Mode: Run Once for All Items
//
// Input: response of "GHL Get Conversation History"
//   (GET /conversations/{conversationId}/messages)
//
// Does three things:
//   1. Hard gate: if the contact is already tagged for manual review / opted
//      out, or has DND on, stop here so Eric never texts them again.
//   2. Deterministic opt-out detection (carrier keywords). Compliance must not
//      depend on the LLM remembering to emit [TRIGGER_HANDOFF].
//   3. Builds the transcript + new-message prompt that Eric receives.

const config = $('Eric Config').first().json;
const batch = $('Debounce & Combine').first().json;
const contact = $('GHL Upsert Contact').first().json.contact || {};
const inboundLog = $('GHL Log Inbound Message').first().json;

// ---- 1. Stop if a human already owns this lead ---------------------------
const tags = (contact.tags || []).map((t) => String(t).toLowerCase());
const blockedTags = [config.handoffTag, config.optOutTag].map((t) => t.toLowerCase());
if (contact.dnd === true || tags.some((t) => blockedTags.includes(t))) {
  return [];
}

// ---- 2. Deterministic opt-out keywords -----------------------------------
const OPT_OUT_EXACT = new Set([
  'stop', 'stopall', 'stop all', 'unsubscribe', 'cancel', 'end', 'quit',
  'remove', 'remove me', 'opt out', 'optout', 'revoke',
]);
const OPT_OUT_PHRASE = /\b(unsubscribe|remove me|take me off|stop texting|stop messaging|opt[\s-]?out|do not (text|contact) me|don'?t (text|contact) me)\b/i;

const normalize = (s) => s.toLowerCase().replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim();
const forcedOptOut =
  batch.individualMessages.some((m) => OPT_OUT_EXACT.has(normalize(m))) ||
  OPT_OUT_PHRASE.test(batch.combinedMessage);

// ---- 3. Transcript -------------------------------------------------------
const res = $input.first().json || {};
const rawMessages = Array.isArray(res.messages?.messages)
  ? res.messages.messages
  : Array.isArray(res.messages)
    ? res.messages
    : [];

const history = rawMessages
  .filter((m) => m && typeof m.body === 'string' && m.body.trim().length > 0)
  .filter((m) => m.id !== inboundLog.messageId) // the burst we just logged
  .sort((a, b) => new Date(a.dateAdded) - new Date(b.dateAdded))
  .slice(-Number(config.historyLimit))
  .map((m) => `${m.direction === 'inbound' ? 'Lead' : 'Eric/Team'}: ${m.body.trim()}`);

const leadName = [contact.firstName, contact.lastName].filter(Boolean).join(' ') || 'Unknown';

const userPrompt = [
  `Lead name: ${leadName}`,
  `Lead phone: ${batch.phoneNumber}`,
  '',
  'Conversation history (oldest first):',
  history.length > 0 ? history.join('\n') : '(no prior messages - this is the first contact)',
  '',
  `New message(s) from the lead (${batch.messageCount} text${batch.messageCount === 1 ? '' : 's'} received together):`,
  batch.combinedMessage,
  '',
  "Write Eric's next SMS reply only. No quotation marks, no labels, no sign-off.",
].join('\n');

return [
  {
    json: {
      userPrompt,
      forcedOptOut,
      contactId: contact.id,
      ghlConversationId: inboundLog.conversationId,
      phoneNumber: batch.phoneNumber,
      twilioNumber: batch.twilioNumber,
      lastMessageSid: batch.lastMessageSid,
    },
  },
];

// n8n Code node: "Parse Eric Reply"
// Mode: Run Once for All Items
//
// Input: output of the "Eric (Claude)" Anthropic node.
// Output fields consumed downstream:
//   ericReplyText     - SMS text with the [TRIGGER_HANDOFF] flag removed
//   handoff           - true -> tag contact for manual review in GHL
//   optOut            - true -> also tag opt-out + set SMS DND in GHL
//   sendReply         - true -> send ericReplyText via Twilio and log to GHL
//   handoffTags       - tags to add to the GHL contact
//   ghlConversationId, contactId, phoneNumber, twilioNumber

const HANDOFF_FLAG = '[TRIGGER_HANDOFF]';

const config = $('Eric Config').first().json;
const ctx = $('Build Eric Context').first().json;
const res = $input.first().json || {};

// The Anthropic node returns either a merged string or a content-block array.
let raw = '';
if (typeof res.merged_response === 'string') {
  raw = res.merged_response;
} else if (Array.isArray(res.content)) {
  raw = res.content
    .filter((block) => block && block.type === 'text' && typeof block.text === 'string')
    .map((block) => block.text)
    .join('\n');
} else if (typeof res.text === 'string') {
  raw = res.text;
}

const modelHandoff = raw.includes(HANDOFF_FLAG);
const optOut = ctx.forcedOptOut === true;
const handoff = modelHandoff || optOut;

const ericReplyText = raw
  .split(HANDOFF_FLAG).join('')
  .replace(/^\s*(Eric|Eric\/Team)\s*:\s*/i, '')
  .replace(/^["'“”]+|["'“”]+$/g, '')
  .trim();

if (!handoff && ericReplyText.length === 0) {
  throw new Error('Eric returned an empty reply without a handoff flag. Raw response: ' + JSON.stringify(res));
}

const handoffTags = [];
if (handoff) handoffTags.push(config.handoffTag);
if (optOut) handoffTags.push(config.optOutTag);

return [
  {
    json: {
      ericReplyText,
      handoff,
      optOut,
      // Never text an opted-out number. A non-opt-out handoff may still send
      // Eric's short acknowledgement (e.g. "Got it, looping in a teammate.").
      sendReply: !optOut && ericReplyText.length > 0,
      handoffTags,
      ghlConversationId: ctx.ghlConversationId,
      contactId: ctx.contactId,
      phoneNumber: ctx.phoneNumber,
      twilioNumber: ctx.twilioNumber,
    },
  },
];
